#: Bonus de score par défaut (en %) selon le code de la rareté.
DEFAULT_BONUS = {"commune": 0, "rare": 5, "epique": 10, "legendaire": 20}


def copy_rarities(apps, schema_editor):
    """Avant : la rareté était celle de la carte. Maintenant : celle de
    l'exemplaire. Les exemplaires gardent la rareté qu'avait leur carte ;
    le champion d'un poste devient le premier de ses 5 champions."""
    Rarity = apps.get_model("cards", "Rarity")
    UserCard = apps.get_model("cards", "UserCard")
    PackOpeningCard = apps.get_model("cards", "PackOpeningCard")
    RosterSlot = apps.get_model("cards", "RosterSlot")
    RosterPick = apps.get_model("cards", "RosterPick")

    for rarity in Rarity.objects.all():
        rarity.score_bonus = DEFAULT_BONUS.get(rarity.code, rarity.order * 5)
        rarity.save(update_fields=["score_bonus"])
    top = Rarity.objects.order_by("-order").first()
    rare = Rarity.objects.filter(code="rare").first() or Rarity.objects.order_by("order").first()
    if top:
        top.fusion_cost = 0
        top.exchange_cost = 1
        top.exchange_rarity = rare
        top.save(update_fields=["fusion_cost", "exchange_cost", "exchange_rarity"])

    for model in (UserCard, PackOpeningCard):
        for item in model.objects.select_related("card"):
            item.rarity_id = item.card.rarity_id
            item.save(update_fields=["rarity"])

    for slot in RosterSlot.objects.exclude(champion=None):
        RosterPick.objects.create(slot=slot, composition=1, champion_id=slot.champion_id)


